01XhF99RNUqVwMiW.command:
// Soigne le jeton sélectionné selon le Taux de guérison complet ou la moitié.
let applyChanges = false;
new Dialog({
    title: game.i18n.localize('DL.MacroHealTitle'),
    content: `
    <form>
      <div class="form-group">
        <label>` + game.i18n.localize('DL.MacroHealChoose') + `</label><br/>
</div>
<div class="form-group">
<table>
<tr>
<td>
<input type="radio" name="healingrate" id="true" checked />
                        <label for="true">` + game.i18n.localize('DL.MacroHealHealingRate') + `</label>
<td/>
</tr>
<tr>
<td>
<input type="radio" name="healingrate" id="false" />
                        <label for="false">` + game.i18n.localize('DL.MacroHealHalfHealingRate') + `</label>
<td/>
</tr>
</table>


</div>
    </form>
    `,
    buttons: {
        yes: {
            icon: "<i class='fas fa-check'></i>",
            label: game.i18n.localize('DL.MacroHealApplyHealing'),
            callback: () => applyChanges = true
        },
        no: {
            icon: "<i class='fas fa-times'></i>",
            label: game.i18n.localize('DL.MacroCancel')
        },
    },
    default: "yes",
    close: html => {
        if (applyChanges) {
            let fullHealingRate = html.find('[name="healingrate"]')[0].checked || false;
            canvas.tokens.controlled.forEach(t => t.actor.applyHealing(fullHealingRate))
        }
    }
}).render(true);

